# Briefing PWA — self-installing script
# Draai dit in C:\Users\Gebruiker\claude-apps
# Het script: maakt briefing/ folder, schrijft alle files, doet git commit + push.

$ErrorActionPreference = "Stop"

# Check: zijn we in claude-apps?
if (-not (Test-Path ".git")) {
    Write-Host "FOUT: dit script moet draaien in de claude-apps repo root." -ForegroundColor Red
    Write-Host "Doe eerst: cd C:\Users\Gebruiker\claude-apps" -ForegroundColor Yellow
    exit 1
}

Write-Host "Briefing PWA installeren..." -ForegroundColor Cyan

# Files (base64-encoded)
$files = @{
  "README.md" = ""
  "netlify.toml" = ""
  "netlify/functions/briefing.js" = ""
  "package.json" = "ewogICJuYW1lIjogImRjYS1icmllZmluZy1wd2EiLAogICJ2ZXJzaW9uIjogIjEuMC4wIiwKICAiZGVzY3JpcHRpb24iOiAiUGVyc29vbmxpamtlIG9jaHRlbmRicmllZmluZyBQV0Egdm9vciBKb3AgRGVsZW1hcnJlIiwKICAicHJpdmF0ZSI6IHRydWUsCiAgInR5cGUiOiAibW9kdWxlIiwKICAiZW5naW5lcyI6IHsKICAgICJub2RlIjogIj49MjAiCiAgfQp9Cg=="
  "public/app.js" = ""
  "public/apple-touch-icon.png" = ""
  "public/icon-192.png" = ""
  "public/icon-512-maskable.png" = ""
  "public/icon-512.png" = ""
  "public/index.html" = ""
  "public/manifest.json" = ""
  "public/sw.js" = ""
}

# Schrijf alle files
foreach ($entry in $files.GetEnumerator()) {
    $path = "briefing/" + $entry.Key
    $dir = Split-Path $path -Parent
    if ($dir -and -not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    $bytes = [Convert]::FromBase64String($entry.Value)
    [IO.File]::WriteAllBytes($path, $bytes)
    Write-Host "  + $path" -ForegroundColor Gray
}

Write-Host ""
Write-Host "Files geschreven. Nu git commit + push..." -ForegroundColor Cyan

# Git config check
$email = git config user.email
if (-not $email) {
    git config --global user.email "jdelemarre@gmail.com"
    git config --global user.name "Jop Delemarre"
}

git add briefing
git commit -m "feat: briefing PWA"
git push

Write-Host ""
Write-Host "KLAAR. Netlify bouwt nu automatisch. Check Netlify dashboard voor URL." -ForegroundColor Green
Write-Host ""
Write-Host "Volgende stappen:" -ForegroundColor Yellow
Write-Host "  1. Notion integration aanmaken op https://www.notion.so/my-integrations"
Write-Host "  2. Integration delen met Action Board"
Write-Host "  3. Env vars zetten in Netlify (NOTION_TOKEN, ANTHROPIC_API_KEY, ACCESS_KEY)"
Write-Host "  4. URL openen op iPhone met ?key=ACCESS_KEY"
